import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

const Login = (props) => {
  const [credentials, setCredentials] = useState({ email: "", password: "" });
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Make sure your backend is running on port 5000
      const response = await fetch("http://localhost:5000/api/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: credentials.email,
          password: credentials.password,
        }),
      });

      // Check if response is ok
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const json = await response.json();
      console.log('Login response:', json);
      
      if (json.success) {
        // Handle both possible token field names from backend
        const token = json.authtoken || json.authToken || json.token;
        if (token) {
          localStorage.setItem("token", token);

          // Call refresh function if provided
          if (props.refreshAuthState) {
            props.refreshAuthState();
          }

          props.showAlert("Welcome back! Successfully logged in.", "success");
          navigate("/");
        } else {
          console.error('No token received:', json);
          props.showAlert("Login successful but no token received", "warning");
        }
      } else {
        // Handle various error message formats
        const errorMessage = json.error || json.message || json.errors || "Invalid credentials";
        props.showAlert(errorMessage, "danger");
      }
    } catch (error) {
      console.error('Login error:', error);
      // More specific error handling
      if (error.message.includes('Failed to fetch')) {
        props.showAlert("Cannot connect to server. Please check if your backend is running on port 5000.", "danger");
      } else if (error.message.includes('HTTP error')) {
        props.showAlert("Server error. Please try again later.", "danger");
      } else {
        props.showAlert("Login failed. Please check your connection and try again.", "danger");
      }
    } finally {
      setLoading(false);
    }
  };

  const onChange = (e) => {
    setCredentials({ ...credentials, [e.target.name]: e.target.value });
  };

  return (
    <div className="container">
      <div className="row">
        <div className="col-md-6" style={{ maxWidth: '500px', margin: '0 auto' }}>
          <div className="card fade-in">
            <div className="card-header text-center">
              <div className="auth-header">
                <div className="auth-icon">
                  <i className="fas fa-sign-in-alt"></i>
                </div>
                <h2 className="mb-2">Welcome Back</h2>
                <p className="text-muted mb-0">Sign in to your Diary Desk account</p>
              </div>
            </div>
            <div className="card-body">
              <form onSubmit={handleSubmit}>
                <div className="form-group mb-3">
                  <label htmlFor="email" className="form-label">
                    <i className="fas fa-envelope me-2"></i>Email Address
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    value={credentials.email}
                    name="email"
                    onChange={onChange}
                    placeholder="Enter your email address"
                    required
                    autoComplete="email"
                  />
                </div>
                
                <div className="form-group mb-3">
                  <label htmlFor="password" className="form-label">
                    <i className="fas fa-lock me-2"></i>Password
                  </label>
                  <div className="password-input-group position-relative">
                    <input
                      type={showPassword ? "text" : "password"}
                      name="password"
                      className="form-control"
                      id="password"
                      value={credentials.password}
                      onChange={onChange}
                      placeholder="Enter your password"
                      required
                      autoComplete="current-password"
                    />
                    <button
                      type="button"
                      className="btn btn-outline-secondary position-absolute end-0 top-0 h-100"
                      onClick={() => setShowPassword(!showPassword)}
                      aria-label={showPassword ? "Hide password" : "Show password"}
                      style={{ zIndex: 10 }}
                    >
                      <i className={`fas ${showPassword ? 'fa-eye-slash' : 'fa-eye'}`}></i>
                    </button>
                  </div>
                </div>

                <button
                  type="submit"
                  className="btn btn-primary btn-lg w-100"
                  disabled={loading || !credentials.email || !credentials.password}
                >
                  {loading ? (
                    <>
                      <span className="spinner-border spinner-border-sm me-2" role="status"></span>
                      Signing in...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-sign-in-alt me-2"></i>Sign In
                    </>
                  )}
                </button>
              </form>

              <div className="text-center mt-3">
                <span>or</span>
              </div>

              <div className="text-center mt-3">
                <p className="mb-0">
                  New to Diary Desk? 
                  <Link to="/signup" className="text-decoration-none ms-1">
                    Create an account
                  </Link>
                </p>
              </div>
            </div>
          </div>

          {/* Welcome Message */}
          <div className="text-center mt-4">
            <div className="row">
              <div className="col-4">
                <div className="text-center">
                  <i className="fas fa-shield-alt text-success"></i>
                  <small className="d-block text-muted">Secure & Private</small>
                </div>
              </div>
              <div className="col-4">
                <div className="text-center">
                  <i className="fas fa-cloud text-primary"></i>
                  <small className="d-block text-muted">Cloud Sync</small>
                </div>
              </div>
              <div className="col-4">
                <div className="text-center">
                  <i className="fas fa-mobile-alt text-info"></i>
                  <small className="d-block text-muted">Mobile Ready</small>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
